-- v1.23 : modèles de prospection (mails d’Anthony du 18/10/2026). Met à jour The Locos, FAV, Natalia M. King, Th/s /s Sh/t ; ajoute Nova Noir, Rosters 2027 (salles / festivals), Réponse Tryo, MaMA, Invitation.
update mail_templates set name=$t$Prospection The Locos$t$, subject=$t${{structure}} x The Locos (ex-SKA-P)$t$, html=$t$Hello {{contact}},<div><br></div><div>Comment vas-tu ?&nbsp;</div><div><br></div><div><div><div><b>The Locos (ex-SKA-P)</b>&nbsp;est en tournée des festivals en 2027 avec 6 nouveaux titres.</div><div><br></div><div>On s’en parle pour ta programmation de {{structure}} ?&nbsp;</div><br></div><div><div><div>Sur scène c’est la grosse fête, ça tourne partout et le public répond présent !!! Tournée des salles en novembre 2026 et début 2027&nbsp;<b>(Cabaret Sauvage, Paris, le 20/11).&nbsp;</b></div><div>Tournée des festivals 2027 avec 6 nouveaux&nbsp;titres. Et toujours&nbsp;<b>les plus grands classiques de SKA-P en live !&nbsp;</b></div><div><br></div></div><div><span style="color:#990000"><b>LIVE &amp; INFOS :</b><strong>&nbsp;</strong></span><a href="https://www.lartboristerie.com/professionnel/the-locos-pro/">https://www.lartboristerie.com/professionnel/the-locos-pro/</a></div><div></div><br></div><div><br></div><div><br></div><div>Je cherche également un slot pour&nbsp;<b>MONTMARTRE, FAV, Th/s /s Sh/t&nbsp;</b>et<b>&nbsp;La Pigñata</b>. Tu aurais de la dispo pour les accueillir ?&nbsp;</div><div><br></div><div><span style="color:#0b5394">•················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:#0b5394">··················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:rgb(11, 83, 148)">•</span><div><div><div><div><span style="color:#004e78"><b>🪩&nbsp;MONTMARTRE</b></span><b>&nbsp;</b><span style="color:rgb(0, 78, 120)">•&nbsp;</span><strong><em>[DJ Set]</em></strong></div><div><span style="color:rgb(0, 78, 120)">•&nbsp;</span><strong><span style="color:#004e78">Nouvel album 2027</span></strong>&nbsp;<span style="color:rgb(0, 78, 120)">•</span></div></div><div><span style="color:rgb(0, 78, 120)"><br></span></div><div><div>Connu pour sa signature French Touch façonnée entre Paris et L.A, MONTMARTRE (Ghost producer de Bon Entendeur) continue d’annoncer son nouvel album avec « Feel Alive » inspiré par le soleil et l’ambiance décontractée de la Californie.</div><div>Entre synthés chaleureux, mélodies lumineuses et groove naturel, il y questionne ce que signifie se sentir vivant sur une production dansante qui fera danser le public en festival.</div><div><br></div></div><div><b style="color:#990000">LIVE &amp; INFOS :&nbsp;</b><a href="https://www.lartboristerie.com/artistes/montmartre/">https://www.lartboristerie.com/artistes/montmartre/</a><span style="color:#0b5394">•················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:#0b5394">··················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:rgb(11, 83, 148)">•</span></div></div><div><div><span style="color:#004e78"><b>🌊&nbsp;FAV</b><b>&nbsp;</b></span><span style="color:rgb(0, 78, 120)">•&nbsp;</span><b><i>[Electro pop]&nbsp;</i></b></div><div><span style="color:rgb(0, 78, 120)">•</span><b style="color:#004e78">&nbsp;Nouvel EP&nbsp;<i>« Dive&nbsp;»</i>&nbsp;(Octobre 2025) + Accompagnement La Belle Électrique (SMAC)&nbsp;</b><span style="color:rgb(0, 78, 120)">•</span></div><div><div><span style="color:rgb(57, 107, 34)"><b><br></b></span></div><div><div>Accompagné par La Belle Électrique (SMAC Grenoble), FAV défend son nouveau live (duo Guitare/synthés et batterie sur scène) mêlant électro, pop et guitares aux accents rock.&nbsp;</div><div>Il enchaîne les premières parties pour Broken Back, Aime Simone, Tim Dup, Papooz….</div><div><b><br></b></div><div><b>Nouvel album + tournée salle à l’automne 2027 !&nbsp;</b></div><div><br></div></div><div><b><span style="color:#990000">LIVE &amp; INFOS :</span><span style="color:#396b22">&nbsp;</span></b><a href="https://www.lartboristerie.com/professionnel/fav-pro/">https://www.lartboristerie.com/professionnel/fav-pro/</a></div></div></div></div><div><span style="color:#0b5394">•················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:#0b5394">··················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:rgb(11, 83, 148)">•</span></div><div><span style="color:#004e78"><b>⚡&nbsp;TH/S /S SH/T</b><b>&nbsp;</b></span><span style="color:rgb(0, 78, 120)">•&nbsp;</span><b><i>[Electro Rock]</i></b></div><div><div><span style="color:rgb(0, 78, 120)">•</span><b style="color:#004e78">&nbsp;</b><b style="color:#004e78">NOUVEL ALBUM&nbsp;«&nbsp;<i>ΛV&nbsp;»</i>&nbsp;LE 30/10/2026&nbsp;</b><span style="color:rgb(0, 78, 120)">•</span></div><span style="color:#0b5394"><br></span><div><div><b>MaMA Festival • 15/10/2026 • Backstage By The Mill • Invitations disponibles</b></div><div><br></div><div>A l’image des signes de<i>&nbsp;« ΛV »</i>&nbsp;(lambda V) qui s’inversent et se reflètent, TH/S /S SH/T font cohabiter le rock et l’électro.</div><div>Trio en live (guitare, basse/synthé et batterie), dans la veine de Carpenter Brut, Justice et Prodigy, Th/s /s Sh/t convainc son public à chacun de ses concerts survoltés !</div><div><br></div><b style="color:#990000">LIVE &amp; INFOS :</b><b style="color:rgb(57, 107, 34)">&nbsp;</b><a href="https://www.lartboristerie.com/professionnel/this-is-shit-pro/">https://www.lartboristerie.com/professionnel/this-is-shit-pro/</a></div></div><div><span style="color:#0b5394">•················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:#0b5394">··················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:rgb(11, 83, 148)">•</span></div><span style="color:#004e78"><b>🔥&nbsp;LA PIGÑATA</b></span><b>&nbsp;</b><span style="color:rgb(0, 78, 120)">•&nbsp;</span><b><i>[Punk Rock Safe]&nbsp;</i></b><div><span style="color:rgb(0, 78, 120)">•</span><b style="color:#004e78">&nbsp;NOUVEL EP&nbsp;«&nbsp;BONNE AMBIANCE&nbsp;» LE 20/11/2026&nbsp;</b><span style="color:rgb(0, 78, 120)">•</span></div><div><br></div><div><b>1ère Partie The Locos (ex-SKA-P) • 20/11/2026 • Cabaret Sauvage • Invitations disponibles</b></div><div><b><br></b></div><div><div>Gus et Larsen (duo basse-batterie) balancent des textes acerbes, drôles et sans concession, où l’ironie devient une arme politique. Avec&nbsp;<i>“Les Vieux”</i>&nbsp;(17/04/26), La Pigñata s’attaque frontalement au mythe d’une génération “mieux avant”. Entre sarcasme et lucidité, le duo démonte les discours nostalgiques et les contradictions d’un héritage qui laisse aux suivants une planète abîmée et des droits fragilisés.</div><div>Avec des titres pensés pour le live, La Pigñata transforme la fosse en pogo, espace de réflexion autant que de fête.&nbsp;</div><div><br></div><div>Après de multiples 1ères parties pour Didier Super, Les Fatals Picard et Lofofora, La Pigñata ouvrira pour The Locos (ex-Ska-P) le 20/11/2026 au Cabaret Sauvage (Paris) et sur plusieurs autres dates en salle.</div><div><br></div></div><div><b style="color:#990000">LIVE &amp; INFOS :</b><b style="color:rgb(57, 107, 34)">&nbsp;</b><a href="https://www.lartboristerie.com/professionnel/la-pignata-pro/">https://www.lartboristerie.com/professionnel/la-pignata-pro/</a></div><div><span style="color:#0b5394">•················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:#0b5394">··················</span><span style="color:rgb(11, 83, 148)">······</span><span style="color:rgb(11, 83, 148)">•</span></div></div><div><br></div>Merci pour ton retour,<div><br></div><div>Bonne journée,</div></div>$t$, updated_at=now() where id='a197964b-9e6b-4133-a7d3-633062e678e1';
update mail_templates set name=$t$Prospection FAV$t$, subject=$t$FAV (Electro Pop) • {{structure}} • Automne 2027$t$, html=$t$<div><div><div><div><div>Bonjour {{contact}},</div><div><br></div><div><b>FAV</b> est en tournée avec son EP <b><i>« Dive »</i></b>.</div><div><br></div><div>Penses-tu que le projet pourrait trouver une place dans la prog de {{structure}} ?</div><div><br></div><div><div>Accompagné par La Belle Électrique (SMAC Grenoble), FAV défend son nouveau live (duo Guitare/synthés et batterie sur scène) mêlant électro, pop et guitares aux accents rock.&nbsp;</div><div>Il enchaîne les premières parties pour Broken Back, Aime Simone, Tim Dup, Papooz….</div><div><br></div><div><b>Nouvel album + tournée salle à l’automne 2027 !&nbsp;</b></div></div><div><br></div><div><b style="color:#990000">LIVE &amp; INFOS :</b>&nbsp;<a href="https://www.lartboristerie.com/professionnel/fav-pro/">https://www.lartboristerie.com/professionnel/fav-pro/</a></div><div><br></div><div>Merci pour ton retour,</div><div><br></div><div>À vite,</div><div><br></div>
</div></div></div></div>$t$, updated_at=now() where id='c21f4467-2451-4743-96d1-55511c106f8f';
update mail_templates set name=$t$Prospection Natalia M. King$t$, subject=$t$Natalia M. King (Blues / Jazz) • {{structure}}$t$, html=$t$<div><div><div><div>Bonjour {{contact}},</div><div><br></div><div><b>Natalia M. King</b>&nbsp;est en tournée avec son album&nbsp;<b><i>« Afroblues »</i></b>.</div><div><br></div><div>Le projet pourrait trouver sa place dans la programmation de {{structure}} ?</div><div><br></div><div><div><div><div><div><div><div>Figure de référence du Jazz, Natalia revient avec<i>&nbsp;son 8ème album «&nbsp;Afroblues&nbsp;»</i>, mélangeant rock blues, afrobeat et électro sur fond d’hommage au Botswana. En trio sur scène (guitare, batterie, synthés), elle voyage entre les États-Unis de son enfance, la France où elle vit aujourd’hui, et l’Afrique de ses racines. Avec sa voix forte, ses grooves qui montent le public en transe et une énergie qui fait autant danser qu’elle touche, Natalia, artiste engagée et rassembleuse (droits LGBTQ+, lutte contre le racisme et le fascisme), transforme chacun de ses concerts en un moment solaire et résolument vivant.</div><div><br></div><div><b>Set Jazz/Blues également disponible !&nbsp;</b></div></div></div><br></div></div></div></div><div><b style="color:#990000">LIVE &amp; INFOS :</b><b style="color:rgb(57, 107, 34)">&nbsp;</b><a href="https://www.lartboristerie.com/professionnel/natalia-m-king-pro/">https://www.lartboristerie.com/professionnel/natalia-m-king-pro/</a></div><div><br></div><div>Merci pour ton retour,</div><div><br></div><div>À vite,</div><br>
</div></div></div>$t$, updated_at=now() where id='d82fe1bf-d98b-40ce-8f76-53bdcf9722f2';
update mail_templates set name=$t$Prospection Th/s /s Sh/t$t$, subject=$t$Th/s /s Sh/t (Rock Electro) • {{structure}}$t$, html=$t$<div><div><div>Bonjour {{contact}},</div><div><br></div><div><b>Th/s /s Sh/t</b> sort son nouvel album<b>&nbsp;<i>« ΛV »</i></b>&nbsp;le 30/10/2026&nbsp;(Label Upton Park).</div><div><br></div><div>Penses-tu que le groupe peut trouver sa place dans la programmation de {{structure}} ?</div><div><br></div><div><div><b>MaMA Festival • 15/10/2026 • Backstage By The Mill • Invitations disponibles</b></div><div><br></div></div><div><div><div>A l’image des signes de<i>&nbsp;« ΛV »</i>&nbsp;(lambda V) qui s’inversent et se reflètent, TH/S /S SH/T font cohabiter le rock et l’électro.</div><div>Trio en live (guitare, basse/synthé et batterie), dans la veine de Carpenter Brut, Justice et Prodigy, Th/s /s Sh/t convainc son public à chaque concert !</div><div><br></div></div><b style="color:#990000">LIVE &amp; INFOS :</b><b style="color:rgb(57, 107, 34)">&nbsp;</b><a href="https://www.lartboristerie.com/professionnel/this-is-shit-pro/">https://www.lartboristerie.com/professionnel/this-is-shit-pro/</a></div><div><br></div><div>Merci pour ton retour,</div><div><br></div><div>À très vite,</div><div><br></div>
</div></div>$t$, updated_at=now() where id='23984820-811a-4ecb-999f-5da3b26c8608';
insert into mail_templates (project_id, kind, name, variant, applies_to, subject, html) select (select id from projects where name=$t$Nova Noir$t$), 'prospection', $t$Prospection Nova Noir$t$, null, 'all', $t$Nova Noir (Rock Alternatif) x {{structure}}$t$, $t$Bonjour {{contact}},<div><br></div><div>Nova Noir s’attaque aux festivals français après deux tournées en Chine devant plus de 10 000 spectateurs.</div><div><br></div><div>Penses-tu que le groupe peut trouver sa place dans ta programmation 2027 ?</div><div><br></div><div>Rejoint à la batterie sur scène par&nbsp;<b>Ion Meunier</b>&nbsp;(Shaka Ponk) ou&nbsp;<b>Enzo Gabert</b>&nbsp;(Skip The Use),&nbsp;Nova Noir frappe fort avec des guitares lourdes mêlées aux machines&nbsp;et des voix qui saturent.&nbsp;Leurs textes, alternant français et anglais, parlent d’intime, de sexe, de colère et de fragilité, mais aussi de politique.</div><div><div><div>Avec 9 titres sortis entre 2025 et 2026, le groupe travaille actuellement sur son premier album prévu pour 2027.</div></div><div><br></div><div><b style="color:#990000">LIVE &amp; INFOS :&nbsp;</b><a href="https://www.lartboristerie.com/professionnel/nova-noir-pro/">https://www.lartboristerie.com/professionnel/nova-noir-pro/</a></div><div><br></div>Merci pour ton retour,</div><div><br></div><div>À vite,</div><div><br>
</div>$t$ where not exists (select 1 from mail_templates where name=$t$Prospection Nova Noir$t$);
